import{_ as i,o,c as l,a4 as c}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"mi-cli 主线说明","description":"","frontmatter":{"title":"mi-cli 主线说明","date":"2026-04-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_mi-cli-mainline-zh.md","filePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_mi-cli-mainline-zh.md"}'),d={name:"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_mi-cli-mainline-zh.md"};function a(t,e,s,n,r,p){return o(),l("div",null,[...e[0]||(e[0]=[c(`<h1 id="mi-cli-主线说明" tabindex="-1">mi-cli 主线说明 <a class="header-anchor" href="#mi-cli-主线说明" aria-label="Permalink to &quot;mi-cli 主线说明&quot;">​</a></h1><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p><code>mi-cli</code> 是 HomeSense Studio V1 的唯一米家控制核心。HA 和 <code>hami-cli</code> 只保留为历史参考，不再作为当前家庭娱乐演示链路的活跃依赖。</p><p>V1 目标是支撑可实测的家庭电视场景：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Chat / Workflow</span></span>
<span class="line"><span>  -&gt; mi-cli 场景、小爱、红外、MIoT 控制</span></span>
<span class="line"><span>  -&gt; adb-cli 电视 App 操控</span></span>
<span class="line"><span>  -&gt; Bilibili TV 演示闭环</span></span></code></pre></div><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>登录必须使用米家 App 扫码：</p><ul><li><code>login_qr</code>：生成二维码登录信息</li><li><code>prepare_login</code>：兼容别名，等同于 <code>login_qr</code></li><li><code>login_status</code>：检查登录状态，并在扫码完成后保存 token</li><li><code>login_logout</code>：清理本地登录状态</li></ul><p>登录状态固定返回：</p><ul><li><code>logged_in</code></li><li><code>token_valid</code></li><li><code>has_saved_login</code></li><li><code>user_id</code></li><li><code>auth_fields_present</code></li><li><code>pending_qr</code></li><li><code>qr.login_url</code></li><li><code>qr.qr_image</code></li><li><code>qr.lp_url</code></li><li><code>next_steps.should_scan_qr</code></li></ul><p>Token 会尝试通过 <code>serviceLogin -&gt; location -&gt; cookies</code> 刷新，但不能假设所有小米服务 token 通用。尤其 <code>speaker_status</code> 仍涉及 Mina 服务，属于实验接口，不进入 V1 主线承诺。</p><h2 id="能力入口" tabindex="-1">能力入口 <a class="header-anchor" href="#能力入口" aria-label="Permalink to &quot;能力入口&quot;">​</a></h2><p>资产发现：</p><ul><li><code>discover</code>：家庭、设备、features、entities、capability_profile</li><li><code>speaker_list</code>：小爱音箱候选</li><li><code>scene_list</code>：米家手动场景</li><li><code>discover_ir</code>：红外控制器</li><li><code>ir_get_keys</code>：红外按键</li></ul><p>控制：</p><ul><li><code>scene_execute</code>：执行米家手动场景</li><li><code>ir_press_key</code>：发送红外按键</li><li><code>speaker_execute</code>：让小爱执行语音指令</li><li><code>speaker_play</code>：让小爱朗读文本</li><li><code>get_prop / set_prop / run_action</code>：MIoT 属性与动作</li></ul><p>推荐控制顺序：</p><ol><li><code>scene_execute</code></li><li><code>ir_press_key</code></li><li><code>speaker_execute</code></li><li><code>set_prop / run_action</code></li></ol><h2 id="小爱与蓝牙边界" tabindex="-1">小爱与蓝牙边界 <a class="header-anchor" href="#小爱与蓝牙边界" aria-label="Permalink to &quot;小爱与蓝牙边界&quot;">​</a></h2><p>小爱 V1 主路径只依赖 MIoT action：</p><ul><li><code>speaker_execute</code> 优先找 <code>execute-text-directive</code></li><li>次选 <code>execute_directive</code></li><li>再次选 <code>message_router.post</code></li><li><code>speaker_play</code> 优先找 <code>play-text</code></li></ul><p>蓝牙能力只承认米家云或网关已经暴露出来的设备能力。项目不承诺任意第三方蓝牙设备直控。</p><h2 id="后端入口" tabindex="-1">后端入口 <a class="header-anchor" href="#后端入口" aria-label="Permalink to &quot;后端入口&quot;">​</a></h2><p>后端已经把 <code>mi-cli</code> 接成一等执行器：</p><ul><li><code>/api/auth/login</code></li><li><code>/api/auth/status</code></li><li><code>/api/auth/logout</code></li><li><code>/api/devices/discover</code></li><li><code>/api/devices/scenes</code></li><li><code>/api/devices/scenes/execute</code></li><li><code>/api/devices/speakers</code></li><li><code>/api/devices/ir/controllers/:parentDid</code></li><li><code>/api/devices/ir/keys/:controllerId</code></li></ul><p>Workflow / Studio 默认电视演示链已经切到 <code>mi-cli.scene_execute</code>、<code>mi-cli.speaker_execute</code> 和 ADB，不再使用 <code>hami-cli</code>。</p><h2 id="前端管理面边界" tabindex="-1">前端管理面边界 <a class="header-anchor" href="#前端管理面边界" aria-label="Permalink to &quot;前端管理面边界&quot;">​</a></h2><p>当前前端固定拆成三类控制面：</p><ul><li><code>Studio</code>：Dify 式资产中枢和工作流控制面，管理 workflow / manifest / plan / agent 等资产。</li><li><code>设备管理</code>：HA 式统一设备注册表，只关心 Device / Entity / Service / State，不承担扫码登录和 CLI 配置。</li><li><code>集成管理</code>：插件和集成管理面，管理 CLI / Agent / A2A / Service / Channel 的存在、配置、登录、通用调用和诊断。</li></ul><p>因此 <code>mi-cli</code> 的二维码登录、米家诊断、场景查询、小爱列表、红外控制器查询都放在 <code>集成管理</code>。<code>mi-cli.discover</code> 发现到的设备会落到本地设备注册表，再由 <code>设备管理</code> 以统一实体方式展示。</p><p>这个拆分的目的：</p><ol><li>避免设备页变成米家控制台。</li><li>让未来 <code>adb-cli</code>、<code>bilibili-cli</code>、Codex / Claude / 小龙虾 A2A、飞书/微信/QQ 渠道都能用同一种集成管理入口接入。</li><li>保持 Chat 和 Workflow 只消费共享底座，不把配置型 UI 堆进对话或画布里。</li></ol>`,32)])])}const h=i(d,[["render",a]]);export{u as __pageData,h as default};
